\[
\mu_{x,t}(\cdot):=e^{\sigma(b)t}\,\mathbb{P}^\dag_x\big(V_t\in\cdot;\; t<\tau_\partial \zeta\big)
\]
as
\[
\mu_{x,t}=\mu_{x,t}^{(1)}+\mu_{x,t}^{(2)},
\]
where
\[
\mu_{x,t}^{(1)}(\cdot):=e^{\sigma(b)t}\,\mathbb{P}^\dag_x\big(V_t\in\cdot;\; t<\tau_\partial \wedge\tau_y^+\big),
\]
and
\[
\mu_{x,t}^{(2)}(\cdot):=e^{\sigma(b)t}\,\mathbb{P}^\dag_x\big(V_t\in\cdot;\; \tau_y^+<t<\tau_\partial\big).
\]

By \cref{two-sided-exit}, along with a monotonicity of roots argument and \cref{sigma-monotonicity}, we have $\sigma(b, y)>\sigma(b)$ imply that there exists $\varepsilon>0$ with $\sigma(b, y)-\varepsilon>\sigma(b)$ and $\mathbb{E}_x^\dag\big[e^{(\sigma(b, y)-\varepsilon)(\tau_\partial \wedge\tau_y^+)}\big]<\infty.$ Therefore, 
\[
\mathbb{P}^\dag_x\big(t<\tau_\partial \wedge\tau_y^+\big)
=o\;\!\big(e^{-(\sigma(b, y)-\varepsilon)t}\big).
\]
Therefore the total variation norm of $\mu_{x,t}^{(1)}$ satisfies
\[
\|\mu_{x,t}^{(1)}\|_{\mathrm{TV}}
= e^{\sigma(b)t}\,\mathbb{P}_x\big(t<\tau_\partial\wedge\tau_y^+\big)
=o\;\!\big(e^{-(\sigma(y,b)-\varepsilon-\sigma(b))t}\big),
\]
as $t\to\infty$. Thus $\mu_{x,t}^{(1)}\to 0$ in total variation.


By the strong Markov property at time $\tau_y^+$ we may write for any measurable set $B$,
